def transform(grid):
    rows = len(grid)
    cols = len(grid[0])

    # First, identify uniform rows and columns
    uniform_rows = set()
    for i in range(rows):
        row_vals = grid[i]
        if all(v == row_vals[0] for v in row_vals):
            uniform_rows.add(i)

    uniform_cols = set()
    for j in range(cols):
        col_vals = [grid[i][j] for i in range(rows)]
        if all(v == col_vals[0] for v in col_vals):
            uniform_cols.add(j)

    # Build output grid
    output = [[0] * cols for _ in range(rows)]
    for i in range(rows):
        for j in range(cols):
            if i in uniform_rows or j in uniform_cols:
                output[i][j] = 2
            else:
                output[i][j] = grid[i][j]

    return output
